package oepul.o6_24

import rego.v1

# Zusammenfassung: ÖPUL-Förderverpflichtungen (sanktionsrelevant nach GSP-AV § 48),
# wasserrechtliche Basisbefunde und Hinweise.

commitment_violations contains {"rule_id": "o6_24.fert.n_limit", "parcel_id": pid, "detail": d} if {
	some pid, d in n_limit_exceeded
	not has_increased_n_permit(pid)
}

commitment_violations contains {"rule_id": "o6_24.fert.period", "parcel_id": pid, "detail": dates} if {
	some pid, dates in applications_outside_period
}

commitment_violations contains {"rule_id": "o6_24.fert.increase_10pct_conditions", "parcel_id": pid, "detail": keys} if {
	some pid, keys in increase_10pct_not_valid
	n_limit_exceeded[pid]
}

commitment_violations contains {"rule_id": "o6_24.fert.separate_plot", "parcel_id": pid, "detail": "Teilflächen mit höherer Düngeklasse als eigener Schlag zu beantragen"} if {
	separate_plot_required[pid]
}

commitment_violations contains {"rule_id": "o6_24.records.farm", "parcel_id": null, "detail": v} if {
	some v in farm_record_violations
}

commitment_violations contains {"rule_id": "o6_24.records.plot", "parcel_id": pid, "detail": missing} if {
	some pid, missing in plot_record_missing
}

commitment_violations contains {"rule_id": "o6_24.records.one_week", "parcel_id": pid, "detail": dates} if {
	some pid, dates in late_entries
}

commitment_violations contains {"rule_id": "o6_24.apply.opwrrl_code", "parcel_id": pid, "detail": "Bewilligungsfläche nicht mit OPWRRL gekennzeichnet"} if {
	some pid in opwrrl_code_missing
}

baseline_findings contains {"rule_id": "o6_24.gwsp.permit_required", "parcel_id": pid, "detail": reasons} if {
	some pid, reasons in gwsp_permit_required_reasons
}

baseline_findings contains {"rule_id": "o6_24.gwsp.wrg_175_210", "parcel_id": pid, "detail": d} if {
	some pid, d in wrg_permit_required
}

baseline_findings contains {"rule_id": "o6_24.gwsp.wg2_permits", "parcel_id": null, "detail": k} if {
	some k in wg2_permit_missing
}

baseline_findings contains {"rule_id": "o6_24.fert.soy", "parcel_id": pid, "detail": "Sojabohnendüngung ohne zulässige Begründung"} if {
	soy_fertilization_not_justified[pid]
}

notes contains {"rule_id": "o6_24.fert.napv_reference", "parcel_id": pid, "detail": "keine Tabellenobergrenze – NAPV-Obergrenze maßgeblich (nicht in Quellen)"} if {
	napv_limit_required[pid]
}

notes contains {"rule_id": "o6_24.fert.period_row_assumed", "parcel_id": pid, "detail": "Kultur in Tab. 4 nicht eindeutig – Zeile 'andere Kulturen außer Begrünungen' angenommen"} if {
	period_row_assumed[pid]
}

notes contains {"rule_id": "o6_24.notice2026.individual_request", "parcel_id": pid, "detail": "einzelflächenbezogenes Ansuchen auf höhere Gewalt erforderlich"} if {
	individual_force_majeure_request_required[pid]
}

notes contains {"rule_id": "o6_24.gen.force_majeure_deadline", "parcel_id": null, "detail": c} if {
	some c in force_majeure_late
}

notes contains {"rule_id": "o6_24.gen.combination", "parcel_id": pid, "detail": c} if {
	some pid, c in combination_conflicts
}

notes contains {"rule_id": "o6_24.gen.area_cap", "parcel_id": pid, "detail": t} if {
	some pid, t in cap_exceeded_parcels
}

decision := {
	"measure": "o6_24",
	"year": farm_year,
	"wrrl_arable_area_ha": wrrl_arable_area_ha,
	"min_participation_met": min_participation_met_bool,
	"contract_valid": contract_valid_bool,
	"participation_eligible": participation_eligible_bool,
	"participation_reasons": participation_reasons,
	"eligible_parcels": eligible_parcels,
	"parcel_ineligibility": parcel_ineligibility,
	"eligible_area_ha": eligible_area_ha,
	"premium_rate_eur_per_ha": premium_rate_or_null,
	"gross_premium_eur": gross_premium_eur,
	"content_reduction_percent": content_reduction_percent,
	"premium_after_modulation_eur": premium_after_modulation,
	"modulation_factor": modulation_factor,
	"n_limits_kg_per_ha": n_limit_kg_per_ha,
	"commitment_violations": commitment_violations,
	"baseline_findings": baseline_findings,
	"notes": notes,
}

min_participation_met_bool if {
	min_participation_met
} else := false

contract_valid_bool if {
	contract_valid
} else := false

participation_eligible_bool if {
	participation_eligible
} else := false

default premium_rate_or_null := null

premium_rate_or_null := premium_rate_eur_per_ha

package oepul.o6_24

import rego.v1

# Förderverpflichtung Stickstoffdüngung (Maßnahmenblatt 4.1; SRL 2.24 lit. a und b)
# in Verbindung mit GWSP § 4 und Anlage 3 Punkt 1 bis 3 (LGBl. Nr. 47/2026).

tab2 := data.o6_24.gwsp_n_limits_acker.rows

tab3 := data.o6_24.gwsp_n_limits_gemuese.rows

termine := data.o6_24.gwsp_duengetermine

default_class := data.o6_24.gwsp_duengeklassen.default_class_if_unassigned

# Düngeklassenanteile eines Schlages; nicht zugeordnete Flächen gelten als Klasse C.
assigned_classes(p) := object.get(wrrl_of(p), "fertilization_classes", [])

assigned_area(p) := sum([c.area_ha | some c in assigned_classes(p)])

class_shares(p) := array.concat(assigned_classes(p), [{"class": default_class, "area_ha": p.area_ha - assigned_area(p)}]) if {
	p.area_ha - assigned_area(p) > 0.00005
} else := assigned_classes(p)

crop_limits(p) := tab2[crop_name_of(p)]

crop_limits(p) := tab3[crop_name_of(p)] if not tab2[crop_name_of(p)]

# Gewichtetes Mittel der Düngeobergrenzen (Maßnahmenblatt 4.1, Anlage 3 Hinweis 3).
weighted_limit_terms(p) := [term |
	limits := crop_limits(p)
	some c in class_shares(p)
	term := limits[c.class] * c.area_ha
]

base_n_limit(p) := round((sum(weighted_limit_terms(p)) / sum([c.area_ha | some c in class_shares(p)])) * 100) / 100

# Anlage 3 Punkt 2: Erhöhung um 10 % im Ackerbau bei winterharter Gründecke.
increase_10pct_claimed(p) if object.get(wrrl_of(p), ["increase_10pct", "claimed"], false) == true

increase_10pct_valid(p) if {
	is_arable_tab2(p)
	inc := wrrl_of(p).increase_10pct
	inc.claimed == true
	inc.winter_hardy_cover_directly_after_main_crop == true
	inc.cover_fertilized == false
	inc.cover_same_field_and_area == true
	inc.cover_contains_legumes == false
	inc.cover_removed_only_before_spring_sowing == true
	inc.written_notice_before_fertilization == true
}

increase_10pct_invalid_conditions(p) := {k |
	inc := object.get(wrrl_of(p), "increase_10pct", {})
	some k, want in {
		"winter_hardy_cover_directly_after_main_crop": true,
		"cover_fertilized": false,
		"cover_same_field_and_area": true,
		"cover_contains_legumes": false,
		"cover_removed_only_before_spring_sowing": true,
		"written_notice_before_fertilization": true,
	}
	object.get(inc, k, null) != want
}

n_limit_kg_per_ha[p.parcel_id] := round(base_n_limit(p) * 110) / 100 if {
	some p in area_arable_parcels
	increase_10pct_valid(p)
}

n_limit_kg_per_ha[p.parcel_id] := base_n_limit(p) if {
	some p in area_arable_parcels
	crop_limits(p)
	not increase_10pct_valid(p)
}

# Anlage 3 Punkt 1: anzurechnende N-Menge = jahreswirksame Düngung + Nachlieferung aus
# Vorfrucht/Ernterückständen + Stickstoff im Gießwasser.
n_fertilizer_effective(p) := sum([a.n_effective_kg_per_ha | some a in applications_of(p)])

n_accounted_kg_per_ha[p.parcel_id] := total if {
	some p in area_arable_parcels
	total := (n_fertilizer_effective(p) + object.get(wrrl_of(p), "previous_crop_n_credit_kg_per_ha", 0)) + object.get(wrrl_of(p), "irrigation_n_kg_per_ha", 0)
}

n_limit_exceeded[pid] := {"accounted": n_accounted_kg_per_ha[pid], "limit": limit} if {
	some pid, limit in n_limit_kg_per_ha
	n_accounted_kg_per_ha[pid] > limit
}

# Kulturen ohne Tabellenwert: Verweis auf die NAPV-Düngeobergrenzen (Anlage 3 nach Tab. 2,
# Hinweis 1 zu Tab. 3) – NAPV ist nicht Teil der Quellen dieses Runs.
napv_limit_required[p.parcel_id] if {
	some p in area_arable_parcels
	count(applications_of(p)) > 0
	not crop_limits(p)
	not is_fallow(p)
}

# Maßnahmenblatt 4.1: Teilflächen mit höherer Düngeklasse separat düngen -> eigener Schlag
# und separate Aufzeichnungen.
separate_plot_required[p.parcel_id] if {
	some p in area_arable_parcels
	count(assigned_classes(p)) > 1
	object.get(wrrl_of(p), "fertilize_subareas_by_class", false) == true
}

# --- Düngetermine (Anlage 3 Punkt 3, Tab. 4) ---

period_row_name(p) := wrrl_of(p).gwsp_period_crop if {
	is_string(object.get(wrrl_of(p), "gwsp_period_crop", null))
} else := row.row if {
	some row in termine.rows
	crop_name_of(p) in row.crops_tab2_tab3
} else := termine.fallback_row

period_row(p) := row if {
	some row in termine.rows
	row.row == period_row_name(p)
}

period_row_assumed[p.parcel_id] if {
	some p in area_arable_parcels
	not is_string(object.get(wrrl_of(p), "gwsp_period_crop", null))
	crop_name_of(p) in {c | some c in termine.ambiguous_tab2_crops_require_explicit_period_row}
}

period_exempt_type(a) if a.fertilizer_type in {t | some t in termine.excluded_fertilizer_types}

application_in_regular_period(p, a) if {
	row := period_row(p)
	md_in_window(a.date, row.from, row.to)
}

is_winter_barley(p) if period_row_name(p) == "Wintergerste"

winter_barley_special_window(a) if md_in_window(a.date, termine.winter_barley_special.from, termine.winter_barley_special.to)

winter_barley_special_apps(p) := [a |
	some a in applications_of(p)
	not period_exempt_type(a)
	winter_barley_special_window(a)
]

increase_10pct_claimed_bool(p) if {
	increase_10pct_claimed(p)
} else := false

# *) Sonderregelung Wintergerste: verletzte Bedingungen.
winter_barley_special_conditions_violated(p) := {k |
	some k, v in {
		"n_over_30kg": sum([a.n_effective_kg_per_ha | some a in winter_barley_special_apps(p)]) > termine.winter_barley_special.max_n_kg_per_ha,
		"sowing_later_than_6_days": winter_barley_sowing_late(p),
		"no_legume_free_cover_after_harvest": object.get(wrrl_of(p), ["winter_barley_special", "legume_free_cover_or_n_consuming_crop_after_harvest"], false) == false,
		"cover_removed_before_spring": object.get(wrrl_of(p), ["winter_barley_special", "cover_removed_only_before_spring_sowing"], false) == false,
		"increase_10pct_used": increase_10pct_claimed_bool(p),
		"no_written_notice": object.get(wrrl_of(p), ["winter_barley_special", "written_notice_before_fertilization"], false) == false,
	}
	v == true
}

winter_barley_sowing_late(p) if {
	sow := object.get(wrrl_of(p), "sowing_date", null)
	some a in winter_barley_special_apps(p)
	not winter_barley_sowing_ok(a, sow)
} else := false

winter_barley_sowing_ok(a, sow) if {
	is_string(sow)
	days_between(a.date, sow) >= 0
	days_between(a.date, sow) <= termine.winter_barley_special.max_days_fertilization_to_sowing
	month_day(sow) <= termine.winter_barley_special.latest_sowing_md
}

application_allowed_in_period(_, a) if period_exempt_type(a)

application_allowed_in_period(p, a) if {
	not period_exempt_type(a)
	application_in_regular_period(p, a)
}

application_allowed_in_period(p, a) if {
	not period_exempt_type(a)
	is_winter_barley(p)
	winter_barley_special_window(a)
	count(winter_barley_special_conditions_violated(p)) == 0
}

applications_outside_period[p.parcel_id] contains a.date if {
	some p in area_arable_parcels
	not is_fallow(p)
	some a in applications_of(p)
	not application_allowed_in_period(p, a)
}

# Anlage 3 Hinweis zu Tab. 4: Düngung von Begrünungen und brachliegenden Flächen
# grundsätzlich bewilligungspflichtig.
fallow_or_cover_fertilized[p.parcel_id] if {
	some p in area_arable_parcels
	is_fallow(p)
	count(applications_of(p)) > 0
}

# Anlage 3 Hinweis zu Tab. 4: Sojabohne – Düngung nur bei nicht beimpftem Saatgut,
# mangelndem Knöllchenbesatz oder erstmaligem Anbau.
soy_fertilization_not_justified[p.parcel_id] if {
	some p in area_arable_parcels
	crop_name_of(p) == "Sojabohne"
	count(applications_of(p)) > 0
	not object.get(wrrl_of(p), "soy_fertilization_reason", null) in {"non_inoculated_seed", "lacking_nodules", "first_cultivation"}
}

increase_10pct_not_valid[p.parcel_id] := increase_10pct_invalid_conditions(p) if {
	some p in area_arable_parcels
	increase_10pct_claimed(p)
	not increase_10pct_valid(p)
}

package oepul.o6_24

import rego.v1

# Allgemeine Teilnahmebedingungen (Stand April 2026), SRL ÖPUL 2023 Allgemeiner Teil
# und GSP-AV, soweit für o6_24 entscheidungsrelevant.

applicant := object.get(input, ["farm", "applicant"], {})

foerderwerber := data.o6_24.oepul_foerderwerber

# 5.2 / SRL 1.4: zulässige Rechtsformen; Gebietskörperschaften nur bei bestimmten
# Maßnahmen zulässig – o6_24 zählt nicht dazu.
applicant_legal_form_ok if {
	applicant.legal_form in {"natural_person", "registered_partnership"}
}

applicant_legal_form_ok if {
	applicant.legal_form in {"legal_person", "association"}
	object.get(applicant, "public_body_share_percent", 0) <= foerderwerber.max_public_body_share_percent
}

# 5.2 / SRL 1.4: aktiver Landwirt, Bewirtschaftung im eigenen Namen und auf eigene
# Rechnung, Verfügungsgewalt über die beantragten Flächen.
applicant_eligible if {
	applicant_legal_form_ok
	object.get(applicant, "is_active_farmer", false) == true
	object.get(applicant, "own_name_and_account", true) == true
	object.get(applicant, "has_disposal_over_areas", true) == true
}

min_size := data.o6_24.oepul_betriebsmindestgroesse

first_participation_year := object.get(oepul, "first_participation_year", null)

# 5.3 / SRL 1.6.1: Betriebsmindestgröße nur im ersten ÖPUL-Teilnahmejahr.
is_first_oepul_year if first_participation_year == farm_year

minimum_farm_size_met if not is_first_oepul_year

minimum_farm_size_met if {
	is_first_oepul_year
	object.get(input, ["land", "total_area_ha"], 0) >= min_size.agricultural_area_min_ha
}

minimum_farm_size_met if {
	is_first_oepul_year
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= min_size.protected_cultivation_min_ha
}

# 5.6 / SRL 1.4.2.1: geförderte Flächen müssen in Österreich liegen.
parcel_outside_austria(p) if object.get(p, "in_austria", true) == false

# 5.4 / SRL 1.6.3.1: Mindestbewirtschaftung auf Ackerflächen (ausgenommen Ackerfutter).
min_harvest_share := 85

harvest_obligation_met(p) if {
	is_arable_forage(p)
}

harvest_obligation_met(p) if {
	is_fallow(p)
}

harvest_obligation_met(p) if {
	not is_arable_forage(p)
	not is_fallow(p)
	object.get(management_of(p), "harvested_share_percent", 100) >= min_harvest_share
}

harvest_obligation_met(p) if drought_harvest_exemption[p.parcel_id]

harvest_obligation_met(p) if object.get(management_of(p), "force_majeure_recognised", false) == true

min_management_met(p) if {
	not is_arable_forage(p)
	not is_fallow(p)
	object.get(management_of(p), "properly_sown", true) == true
	object.get(management_of(p), "properly_maintained", true) == true
	harvest_obligation_met(p)
}

# 5.4 / SRL 1.6.3.3: Ackerfutterflächen jährlich mindestens einmal vollflächige Mahd
# mit Verbringen des Mähgutes oder vollflächige Beweidung.
min_management_met(p) if {
	is_arable_forage(p)
	object.get(management_of(p), "full_mowing_or_grazing", true) == true
}

# 5.4 / SRL 1.6.3.4: aus der Produktion genommene Flächen: Gründecke und Häckseln/Pflegemahd
# zumindest jedes zweite Jahr.
min_management_met(p) if {
	is_fallow(p)
	object.get(management_of(p), "green_cover_established", true) == true
	object.get(management_of(p), "mulched_within_two_years", true) == true
}

# Anhang L: auf der Einzelfläche mit o6_24 prämienmäßig kombinierbare Maßnahmen.
combinable_with_24 := {c | some c in data.o6_24.srl_anhang_l.row_24_combinable}

combination_conflicts[p.parcel_id] := conflicts if {
	some p in parcels
	measure_code in measures_of(p)
	conflicts := {m | some m in measures_of(p); m != measure_code; not m in combinable_with_24}
	count(conflicts) > 0
}

# 5.5.2: Leistungsüberschneidung – gesetzlich vorgeschriebene Auflagen führen bei o6_24
# nicht zur OP-Codierung (SRL 1.6.2.3 Ausnahme), vertragliche Leistungsüberschneidung schon.
op_required_reasons[p.parcel_id] contains "Leistungsüberschneidung aus Vereinbarung mit der öffentlichen Hand" if {
	some p in parcels
	object.get(p, ["oepul", "public_funding_agreement_overlap"], false) == true
}

op_required_reasons[p.parcel_id] contains "Ernteverpflichtung nicht erfüllt" if {
	some p in area_arable_parcels
	not harvest_obligation_met(p)
}

op_required_reasons[p.parcel_id] contains "unterjährige Flächenweitergabe ohne Weiterführung bis Jahresende" if {
	some p in parcels
	object.get(p, ["oepul", "transferred_mid_year"], false) == true
	object.get(p, ["oepul", "successor_continues_obligations"], false) == false
}

op_required_reasons[p.parcel_id] contains "behördlich vorgeschriebene Ausgleichsfläche/Infrastrukturnutzung" if {
	some p in parcels
	object.get(p, ["oepul", "official_compensation_area"], false) == true
}

op_required_reasons[p.parcel_id] contains "Nichterfüllung durch reines Fremdverschulden" if {
	some p in parcels
	object.get(p, ["oepul", "third_party_fault"], false) == true
}

# 5.5.1 / SRL 1.6.2.2: Nationalparkflächen bleiben bei o6_24 prämienfähig.
national_park_excludes_premium := false

# GSP-AV § 6 Abs. 2: höhere Gewalt binnen drei Wochen ab Möglichkeit geltend machen.
force_majeure_cases := object.get(oepul, "force_majeure_cases", [])

force_majeure_notified_in_time(c) if {
	days_between(c.able_to_notify_date, c.notified_date) <= data.o6_24.gsp_av_hoehere_gewalt.notification_days
}

force_majeure_late contains c if {
	some c in force_majeure_cases
	not c.covered_by_general_recognition == true
	not force_majeure_notified_in_time(c)
}

# GSP-AV § 14 Abs. 2: Betriebsübertragung binnen vier Wochen anzeigen.
farm_transfer_notice_late if {
	t := object.get(oepul, "farm_transfer", null)
	is_object(t)
	days_between(t.effective_date, t.notified_date) > data.o6_24.oepul_fristen.farm_transfer_notification_days
}

# GSP-AV § 27 Abs. 2: Mindestgröße je förderfähiger Fläche 50 m².
parcel_below_min_size(p) if p.area_ha * 10000 < data.o6_24.gsp_av_flaechensanktion.min_parcel_m2

# GSP-AV § 28 Abs. 2: nicht-landwirtschaftliche Nutzung während der Vegetationsperiode
# höchstens 14 Kalendertage und vorab zu melden.
non_agricultural_use_excess(p) if {
	object.get(p, ["oepul", "non_agricultural_use_days_in_vegetation_period"], 0) > data.o6_24.gsp_av_nichtlandwirtschaftliche_nutzung.max_non_agri_days_in_vegetation_period
}

non_agricultural_use_excess(p) if {
	object.get(p, ["oepul", "non_agricultural_use_days_in_vegetation_period"], 0) > 0
	object.get(p, ["oepul", "non_agricultural_use_notified_in_advance"], false) == false
}

# GSP-AV § 9 Abs. 7 / SRL 1.11.1.2: verhinderte Kontrolle -> keine Fördermittel.
controls_obstructed if object.get(oepul, "controls_obstructed", false) == true

package oepul.o6_24

import rego.v1

# Wasserrechtliche Basisanforderungen des Grundwasserschutzprogramms Graz bis
# Bad Radkersburg 2018 (§ 4 Z 4 bis 7, § 6, Anlage 3 Punkt 4 und 5, Hinweis 2).
# Diese Anforderungen sind nicht als ÖPUL-Förderverpflichtungen in SRL 2.24 genannt;
# Abweichungen bedürfen einer wasserrechtlichen Bewilligung (§ 4 Z 7).

# Anlage 3 Punkt 4: Gaben von mehr als 100 kg N/ha in einem Abstand von weniger als drei
# Wochen sind nicht geringfügig (Gleitfenster 21 Tage; siehe Annahmen).
max_n_within_3_weeks := 100

window_n_sum(p, start) := sum([b.n_effective_kg_per_ha |
	some b in applications_of(p)
	days_between(start, b.date) >= 0
	days_between(start, b.date) < 21
])

n_over_100_within_3_weeks[p.parcel_id] contains a.date if {
	some p in area_arable_parcels
	some a in applications_of(p)
	window_n_sum(p, a.date) > max_n_within_3_weeks
}

# Anlage 3 Punkt 4: Zeitraum zwischen N-Düngung und Anbau maximal 10 Tage (ausgenommen Mist
# von Huf- und Klauentieren, Kompost; Wintergerste 6 Tage).
max_days_fertilization_to_sowing := 10

pre_sowing_apps(p) := [a |
	sow := object.get(wrrl_of(p), "sowing_date", null)
	is_string(sow)
	some a in applications_of(p)
	not a.fertilizer_type in {"solid_manure_hoof_claw", "compost"}
	days_between(a.date, sow) >= 0
]

fertilization_too_early_before_sowing[p.parcel_id] contains a.date if {
	some p in area_arable_parcels
	some a in pre_sowing_apps(p)
	days_between(a.date, wrrl_of(p).sowing_date) > max_days_fertilization_to_sowing
}

# Anlage 3 Hinweis 2 / § 32 Abs. 2 lit. f WRG 1959: Bewilligungspflicht über 175 kg N/ha
# (ohne Gründeckung) bzw. 210 kg N/ha (mit Gründeckung, Dauergrünland oder N-zehrender
# Fruchtfolge); Wirtschaftsdünger in feldfallender Wirkung anzurechnen.
wrg_threshold(p) := 210 if {
	object.get(wrrl_of(p), "green_cover_or_n_consuming_rotation", object.get(p, ["operations", "cover_crop", "is_used"], false)) == true
} else := 175

n_field_total(p) := sum([object.get(a, "n_field_kg_per_ha", a.n_effective_kg_per_ha) | some a in applications_of(p)])

wrg_permit_required[p.parcel_id] := {"n_field": n_field_total(p), "threshold": wrg_threshold(p)} if {
	some p in parcels
	object.get(wrrl_of(p), "in_area", false) == true
	n_field_total(p) > wrg_threshold(p)
	object.get(wrrl_of(p), "wrg_permit", false) == false
}

# GWSP § 4 Z 7: jede Abweichung von Z 1 bis 6 bedarf einer wasserrechtlichen Bewilligung.
gwsp_permit_required_reasons[pid] contains "N-Höchstmenge Anlage 3 Punkt 1/2 überschritten" if {
	some pid, _ in n_limit_exceeded
	not has_increased_n_permit(pid)
}

gwsp_permit_required_reasons[pid] contains "Ausbringung außerhalb bewilligungsfreier Zeiträume (Anlage 3 Punkt 3)" if {
	some pid, _ in applications_outside_period
}

gwsp_permit_required_reasons[pid] contains "Düngung von Begrünungen oder brachliegenden Flächen" if {
	fallow_or_cover_fertilized[pid]
}

gwsp_permit_required_reasons[pid] contains "Art und Weise der Ausbringung (Anlage 3 Punkt 4)" if {
	some pid, _ in n_over_100_within_3_weeks
}

gwsp_permit_required_reasons[pid] contains "Art und Weise der Ausbringung (Anlage 3 Punkt 4)" if {
	some pid, _ in fertilization_too_early_before_sowing
}

gwsp_permit_required_reasons[pid] contains "Gemüsebau-Voraussetzungen (Anlage 3 Punkt 5)" if {
	some pid, _ in vegetable_findings
}

has_increased_n_permit(pid) if object.get(wrrl_of(area_arable_parcels[pid]), "increased_n_permit", false) == true

# GWSP § 6: zusätzliche Bewilligungspflichten im Widmungsgebiet 2 (Schongebiet).
wg2_items := {i.key: i | some i in data.o6_24.gwsp_widmungsgebiet2_bewilligungspflichten.items}

wg2_activity_requires_permit(act) if {
	item := wg2_items[act.key]
	not item.threshold_kg
	not item.threshold_ha
	not item.threshold_kg_n_per_ha
}

wg2_activity_requires_permit(act) if act.value > wg2_items[act.key].threshold_kg

wg2_activity_requires_permit(act) if act.value > wg2_items[act.key].threshold_ha

wg2_activity_requires_permit(act) if act.value > wg2_items[act.key].threshold_kg_n_per_ha

wg2_permit_missing contains act.key if {
	some act in object.get(input, ["farm", "gwsp_widmungsgebiet2_activities"], [])
	wg2_activity_requires_permit(act)
	object.get(act, "has_permit", false) == false
}

package oepul.o6_24

import rego.v1

# Teilnahmevoraussetzungen, Vertragszeitraum, Beantragung und Ausstieg
# (Maßnahmenblatt o6_24 Kap. 3, 5, 6; SRL 1.7.1.1, 1.10.5, 2.24;
# Allgemeine Teilnahmebedingungen 5.9, 6).

premium_data := data.o6_24.o6_24_praemie

# Bewirtschaftete Ackerfläche in der Gebietskulisse (inklusive Flächen mit
# Bewilligung zu erhöhten Stickstoffgaben und Brachen; siehe Annahmen).
wrrl_arable_area_ha := sum([p.area_ha | some p in area_arable_parcels])

# Maßnahmenblatt 3.2 / SRL 2.24: mindestens 2,00 ha Ackerfläche in der Gebietskulisse.
min_participation_met if wrrl_arable_area_ha >= premium_data.min_participation_arable_ha

# Maßnahmenblatt 3.1 / 5: Bei Unterschreiten der Mindestteilnahme erlischt der Vertrag.
contract_lapses_this_year if not min_participation_met

application_date := object.get(o624, "measure_application_date", null)

contract_start_year := object.get(o624, "contract_start_year", null)

# Maßnahmenblatt 5: Beantragung vor Vertragsbeginn bis spätestens 31. Dezember des Vorjahres.
application_deadline_met if {
	is_string(application_date)
	is_number(contract_start_year)
	application_date <= sprintf("%d-12-31", [contract_start_year - 1])
}

# Maßnahmenblatt 5 / Allgemeine Teilnahmebedingungen 5.9: letzter Einstieg Förderjahr 2027.
entry_year_allowed if {
	is_number(contract_start_year)
	contract_start_year <= premium_data.last_entry_year
}

deregistration_date := object.get(o624, "deregistration_date", null)

# Maßnahmenblatt 6: Abmeldung im laufenden Jahr -> Maßnahme im betroffenen Förderjahr nicht mehr gültig.
deregistered_for_year if {
	is_string(deregistration_date)
	year_of(deregistration_date) <= farm_year
}

# Maßnahmenblatt 6: Ausstieg erst nach Erfüllung des einjährigen Vertragszeitraumes.
exit_allowed_in_year(y) if {
	is_number(contract_start_year)
	y > contract_start_year
}

deregistration_before_first_year_completed if {
	is_string(deregistration_date)
	not exit_allowed_in_year(year_of(deregistration_date))
}

# Maßnahmenblatt 5 Achtung / SRL 1.10.5.3: Nach Erlöschen (Mindestteilnahme verfehlt),
# Ausstieg, Ausschluss oder einjähriger Nichtabgabe des Mehrfachantrages ist ein
# neuer fristgerechter Maßnahmenantrag erforderlich.
new_application_required if {
	object.get(o624, "lapsed_in_previous_year", false) == true
	contract_start_year < farm_year
}

new_application_required if {
	object.get(o624, "mfa_not_submitted_previous_year", false) == true
	contract_start_year < farm_year
}

new_application_required if {
	object.get(o624, "excluded_previously", false) == true
	contract_start_year < farm_year
}

# Allgemeine Teilnahmebedingungen 6 / SRL 1.10.5.2: automatische Verlängerung einjähriger
# Maßnahmen, Weiterführung durch Abgabe des Mehrfachantrages.
contract_valid if {
	object.get(o624, "measure_application_submitted", false) == true
	application_deadline_met
	entry_year_allowed
	contract_start_year <= farm_year
	not deregistered_for_year
	not new_application_required
}

mfa_submitted if object.get(o624, "multiple_application_submitted", false) == true

# SRL 1.12.1.1: bei einjährigen Maßnahmen kommt bei Nichterfüllung von Förder-
# bzw. Zugangsvoraussetzungen kein Vertrag zustande.
participation_eligible if {
	contract_valid
	mfa_submitted
	min_participation_met
	applicant_eligible
	minimum_farm_size_met
}

participation_reasons contains "Maßnahmenantrag fehlt oder nicht fristgerecht (31.12. des Vorjahres)" if {
	not application_deadline_met
}

participation_reasons contains "Einstieg nach dem Förderjahr 2027 nicht möglich" if {
	not entry_year_allowed
}

participation_reasons contains "Maßnahme im Förderjahr abgemeldet" if deregistered_for_year

participation_reasons contains "neuer Maßnahmenantrag erforderlich (Vertrag erloschen bzw. Ausstieg/Ausschluss/Nichtabgabe MFA)" if {
	new_application_required
}

participation_reasons contains "Mehrfachantrag mit förderrelevanten Flächen nicht abgegeben" if not mfa_submitted

participation_reasons contains "Mindestteilnahme von 2,00 ha Ackerfläche in der Gebietskulisse nicht erreicht – Vertrag erlischt" if {
	not min_participation_met
}

participation_reasons contains "förderwerbende Person nicht teilnahmeberechtigt" if not applicant_eligible

participation_reasons contains "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr nicht erreicht" if {
	not minimum_farm_size_met
}

# Allgemeine Teilnahmebedingungen 6.3 / SRL 1.7.3.1: Maßnahmenübernahme durch anderen Betrieb.
takeover_deadline_md := "04-17" if {
	farm_year in {2023, 2028}
} else := "04-15"

takeover_allowed if {
	t := object.get(o624, "takeover", null)
	is_object(t)
	month_day(t.request_date) <= takeover_deadline_md
	year_of(t.request_date) == farm_year
	t.taking_over_farm_previously_participating == false
	t.expansion_share <= 0.5
}

package oepul.o6_24

import rego.v1

# Prämie (Maßnahmenblatt 7; SRL 2.24 Höhe der Förderung), Modulation, Obergrenze,
# Flächenabweichungen und inhaltliche Sanktionen (Allgemeine Teilnahmebedingungen 8.2,
# 9; SRL 1.9, 1.12; GSP-AV §§ 11, 46 bis 48).

premium_rate_eur_per_ha := r.eur_per_ha if {
	some r in premium_data.rates
	farm_year >= r.from_year
	farm_year <= r.to_year
}

non_eligible_codes := {c | some c in premium_data.non_eligible_codes}

# Gründe, aus denen ein Schlag in der Gebietskulisse nicht prämienfähig ist.
parcel_ineligibility[p.parcel_id] contains "Bewilligung zu erhöhten Stickstoffdüngergaben (Code OPWRRL)" if {
	some p in area_arable_parcels
	object.get(wrrl_of(p), "increased_n_permit", false) == true
}

parcel_ineligibility[p.parcel_id] contains sprintf("Code %s", [c]) if {
	some p in area_arable_parcels
	some c in codes_of(p)
	c in non_eligible_codes
}

parcel_ineligibility[p.parcel_id] contains "Brachfläche (SRL 2.24)" if {
	some p in area_arable_parcels
	is_fallow(p)
}

parcel_ineligibility[p.parcel_id] contains "Mindestbewirtschaftung nicht erfüllt" if {
	some p in area_arable_parcels
	not min_management_met(p)
}

parcel_ineligibility[pid] contains reason if {
	some pid, reasons in op_required_reasons
	area_arable_parcels[pid]
	some reason in reasons
}

parcel_ineligibility[p.parcel_id] contains "Fläche nicht in Österreich" if {
	some p in area_arable_parcels
	parcel_outside_austria(p)
}

parcel_ineligibility[p.parcel_id] contains "Fläche kleiner 50 m²" if {
	some p in area_arable_parcels
	parcel_below_min_size(p)
}

parcel_ineligibility[p.parcel_id] contains "nicht hauptsächlich landwirtschaftlich genutzt" if {
	some p in area_arable_parcels
	non_agricultural_use_excess(p)
}

parcel_ineligibility[p.parcel_id] contains "Fläche nicht für o6_24 im Mehrfachantrag angegeben" if {
	some p in area_arable_parcels
	object.get(p, ["oepul", "declared_for_o6_24"], true) == false
}

parcel_ineligibility[pid] contains "Maßnahmenkombination auf der Einzelfläche nicht zulässig (Anhang L)" if {
	some pid, _ in combination_conflicts
	area_arable_parcels[pid]
}

# Maßnahmenblatt 5: prämienfähige Flächen werden anhand der Gebietskulisse ermittelt.
eligible_parcels contains pid if {
	some pid, _ in area_arable_parcels
	not parcel_ineligibility[pid]
}

eligible_area_ha := sum([area_arable_parcels[pid].area_ha | some pid in eligible_parcels])

# Maßnahmenblatt 5 (Bewilligungsflächen mit OPWRRL kennzeichnen).
opwrrl_code_missing contains p.parcel_id if {
	some p in area_arable_parcels
	object.get(wrrl_of(p), "increased_n_permit", false) == true
	not "OPWRRL" in codes_of(p)
}

gross_premium_eur := round((eligible_area_ha * premium_rate_eur_per_ha) * 100) / 100 if {
	participation_eligible
} else := 0

# Modulation nach Gesamtfläche des Betriebes (Allgemeine Teilnahmebedingungen 9.3).
tier_area(total, tier) := max([0, min([total, tier_upper(tier, total)]) - tier.from_ha_exclusive])

tier_upper(tier, total) := tier.to_ha_inclusive if {
	is_number(tier.to_ha_inclusive)
} else := total

modulation_factor := 1 if {
	object.get(input, ["land", "total_area_ha"], 0) <= 200
} else := f if {
	total := input.land.total_area_ha
	weighted := [w |
		some t in data.o6_24.oepul_modulation.tiers
		w := tier_area(total, t) * t.payout_share
	]
	f := sum(weighted) / total
}

# Inhaltliche Sanktionen (GSP-AV § 48; Allgemeine Teilnahmebedingungen 8.2).
stages := data.o6_24.oepul_sanktionsstufen.stages

findings := object.get(o624, "content_findings", [])

finding_level(f) := min([6, f.base_level + object.get(f, "previous_occurrences_same_obligation", 0)])

stage_percent(level) := 1 if {
	level == 0
	farm_year >= 2027
} else := s.reduction_percent if {
	some s in stages
	s.level == level
}

content_reduction_percent := min([100, sum([stage_percent(finding_level(f)) | some f in findings])])

previous_100pct_reductions := object.get(o624, "previous_100pct_reductions_in_period", 0)

measure_exclusion if {
	content_reduction_percent == 100
	previous_100pct_reductions + 1 >= data.o6_24.oepul_sanktionsstufen.exclusion_after_100pct_count
}

# Flächenabweichung (GSP-AV § 46): Übererklärung > 3 % oder > 2 ha -> Abzug 1,5-fache Differenz.
declared_area := object.get(o624, "declared_area_ha", eligible_area_ha)

determined_area := object.get(o624, "determined_area_ha", declared_area)

area_difference := declared_area - determined_area

area_sanction_applies if {
	area_difference > 0
	area_difference > determined_area * 0.03
}

area_sanction_applies if area_difference > 2

calculation_area_ha := max([0, determined_area - (1.5 * area_difference)]) if {
	area_sanction_applies
} else := min([declared_area, determined_area])

# GSP-AV § 47: Untererklärung – Kürzung bis zu 3 % bei Differenz über 3 %.
under_declaration_reduction_possible if {
	undeclared := object.get(oepul, "undeclared_parcels_area_ha", 0)
	total_declared := object.get(input, ["land", "total_area_ha"], 0)
	undeclared > total_declared * 0.03
}

premium_after_area_and_content := round((((calculation_area_ha * premium_rate_eur_per_ha) * (100 - content_reduction_percent)) / 100) * 100) / 100 if {
	participation_eligible
	not measure_exclusion
	not controls_obstructed
} else := 0

premium_after_modulation := round((premium_after_area_and_content * modulation_factor) * 100) / 100

# Obergrenze für Flächenzahlungen (SRL 1.9.2.1) je Schlag.
area_payment_cap := r.eur_per_ha if {
	some r in data.o6_24.oepul_flaechenzahlung_obergrenzen.rows
	r.key == "general"
	farm_year >= r.year_from
	farm_year <= r.year_to
}

cap_exceeded_parcels[pid] := total if {
	some pid in eligible_parcels
	other := object.get(area_arable_parcels[pid], ["oepul", "other_area_payments_eur_per_ha"], 0)
	total := other + (premium_rate_eur_per_ha * modulation_factor)
	total > area_payment_cap
}

# GSP-AV § 11 / SRL 1.10.7: Auszahlungsbetrag bis 50 Euro kann entfallen.
payment_may_be_waived if {
	premium_after_modulation > 0
	premium_after_modulation <= data.o6_24.oepul_zahlung.min_payment_eur
}

package oepul.o6_24

import rego.v1

# Förderverpflichtung Aufzeichnungen (Maßnahmenblatt 4.2; SRL 2.24) gemäß GWSP § 5.

wrrl_records := object.get(input, ["documentation", "wrrl_records"], {})

aufz := data.o6_24.gwsp_aufzeichnungen

# Maßnahmenblatt 4.2: Betriebsbuch am Betrieb aufzubewahren.
farm_record_violations contains "Betriebsbuch gemäß § 5 GWSP nicht geführt" if {
	object.get(wrrl_records, "farm_book_kept", false) == false
}

farm_record_violations contains "Betriebsbuch nicht am Betrieb aufbewahrt" if {
	object.get(wrrl_records, "kept_at_farm", false) == false
}

# GWSP § 5 Abs. 1: jährliche betriebsbezogene Daten.
farm_record_violations contains sprintf("jährliche Betriebsdaten fehlen: %s", [f.key]) if {
	some f in aufz.farm_annual_fields
	not f.key in {k | some k in object.get(wrrl_records, "annual_fields_recorded", [])}
}

# Maßnahmenblatt 4.2: Aufzeichnungen für alle Schläge, auch ohne Düngung.
farm_record_violations contains "Aufzeichnungen nicht für alle Schläge (auch ohne Düngung) geführt" if {
	object.get(wrrl_records, "records_for_all_plots", false) == false
}

# GWSP § 5 Abs. 3: Aufbewahrung mindestens sieben Jahre.
farm_record_violations contains "Aufbewahrungsdauer unter sieben Jahren" if {
	object.get(wrrl_records, "retention_years", aufz.retention_years_min) < aufz.retention_years_min
}

# GWSP § 5 Abs. 2: schlagbezogene Pflichtangaben.
required_application_fields := ["date", "fertilizer_type", "amount", "n_effective_kg_per_ha"]

plot_record_missing[p.parcel_id] contains sprintf("Düngung %v: %s", [object.get(a, "date", "?"), f]) if {
	some p in area_arable_parcels
	some a in applications_of(p)
	some f in required_application_fields
	object.get(a, f, null) == null
}

plot_record_missing[p.parcel_id] contains f if {
	some p in area_arable_parcels
	not is_fallow(p)
	some f in ["sowing_date", "n_requirement_kg_per_ha", "previous_crop_n_credit_kg_per_ha"]
	object.get(wrrl_of(p), f, null) == null
}

plot_record_missing[p.parcel_id] contains f if {
	some p in area_arable_parcels
	is_string(object.get(wrrl_of(p), "harvest_date", null))
	some f in ["harvested_crop", "yield"]
	object.get(wrrl_of(p), f, null) == null
}

plot_record_missing[p.parcel_id] contains "Einstufung nach Anlage 2B" if {
	some p in area_arable_parcels
	object.get(wrrl_of(p), "class_recorded", true) == false
}

plot_record_missing[p.parcel_id] contains "Stickstoff im Gießwasser" if {
	some p in area_arable_parcels
	object.get(wrrl_of(p), "irrigated", false) == true
	object.get(wrrl_of(p), "irrigation_n_kg_per_ha", null) == null
}

plot_record_missing[p.parcel_id] contains sprintf("PSM %v: %s", [object.get(u, "date", "?"), f]) if {
	some p in area_arable_parcels
	some u in object.get(wrrl_of(p), "psm_applications", [])
	some f in ["product_name", "date", "method", "rate"]
	object.get(u, f, null) == null
}

# GWSP § 5 Abs. 2: Eintragung innerhalb einer Woche nach der Maßnahme.
late_entries[p.parcel_id] contains a.date if {
	some p in area_arable_parcels
	some a in applications_of(p)
	is_string(object.get(a, "recorded_date", null))
	days_between(a.date, a.recorded_date) > aufz.entry_deadline_days
}

